function anaOverview(L){const C=L.map(anaCheck),ev=C.filter(c=>['Đúng hướng','Sai hướng','Hoà'].includes(c.v)),ok=C.filter(c=>c.v=='Đúng hướng').length,bad=C.filter(c=>c.v=='Sai hướng').length,no=C.filter(c=>c.v=='Không có lệnh').length,sumAl=sm2(C,c=>c.alNet),acc=ev.length?ok/ev.length*100:0;
const cards=`<div class="k">${kt('Phân tích đã đánh giá',ev.length+' / '+C.length,'Có lệnh và có hướng rõ')}${kt('Độ đúng hướng',nf(acc,0)+'%',ok+' đúng · '+bad+' sai')}${kt('Lãi/lỗ theo hướng phân tích',usd(sumAl),'Chỉ tính lệnh cùng chiều với phân tích')}${kt('Phân tích không có lệnh',no,'Không có gì để đối chiếu')}</div>`;
const tg=`<span class="hr"><span class="seg"><button class="${LG.cmp=='chart'?'':'on'}" data-lg="cmp:list">Danh sách</button><button class="${LG.cmp=='chart'?'on':''}" data-lg="cmp:chart">Biểu đồ</button></span></span>`;
const body=LG.cmp=='chart'?`<div class="cv" style="height:300px"><canvas id="ac"></canvas></div>`:(C.slice().reverse().map(c=>`<div class="er"><div><b>${esc(c.x.ttl)}</b><span>${fl(c.x.d)} · Phiên ${c.x.sess} · ${c.x.bias} · Key level ${esc(c.x.lv||'—')}</span><span>${c.n} lệnh · Thực tế ${usd(c.net)} · Theo hướng ${usd(c.alNet)}${c.inZ!=null?' · Entry trong vùng '+nf(c.inZ,0)+'%':''}</span></div><div style="text-align:right">${chip(c.v,vcol(c.v))}</div></div>`).join('')||'<p class="nt">Không có phân tích trong khoảng này.</p>');
return`<div class="card"><h3>Đối chiếu phân tích với kết quả thực tế${tg}</h3>${cards}${body}<p class="nt">Cách tính: "Đúng hướng" khi các lệnh cùng chiều với phân tích (Tăng = Buy, Giảm = Sell) có lãi tổng cộng; "Sai hướng" khi lỗ; "Hoà" khi bằng 0. Phân tích "Đi ngang" không được đánh giá. "Entry trong vùng" là tỉ lệ lệnh có giá vào nằm trong khoảng key level (khi ghi ít nhất 2 số).</p></div>`}
function anaChart(){const L=LGD.ana.filter(x=>inR(x.d)).sort((a,b)=>a.d<b.d?-1:1),C=L.map(anaCheck),col=c=>c.v=='Đúng hướng'?cv('ok'):c.v=='Sai hướng'?cv('bad'):cv('sl');
return new Chart(document.getElementById('ac'),{type:'bar',data:{labels:C.map(c=>fl(c.x.d)),datasets:[{type:'bar',label:'Theo hướng phân tích',data:C.map(c=>+c.alNet.toFixed(2)),backgroundColor:C.map(col),borderRadius:6,maxBarThickness:28},{type:'line',label:'Lãi/lỗ thực tế trong ngày',data:C.map(c=>+c.net.toFixed(2)),borderColor:cv('gold'),backgroundColor:cv('gold'),borderWidth:2,pointRadius:4,tension:.25}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'},tooltip:{callbacks:{afterBody:i=>{const c=C[i[0].dataIndex];return[c.x.ttl,'Hướng: '+c.x.bias+' · Phiên '+c.x.sess,'Kết quả: '+c.v]}}}},scales:{x:{grid:{display:false}},y:{grid:{color:cv('line')},border:{display:false},ticks:{callback:v=>usd(v)}}}}})}
function lgAna(){const q=rng(),one=q[0]==q[1],L=LGD.ana.filter(x=>inR(x.d)).sort((a,b)=>a.d<b.d?1:-1),op=o=>`<option>${o}</option>`,
rw=x=>{const o=one||LG.open==x.id;return`<div class="an"><div class="ah" data-lg="ao:${x.id}"><div><b>${esc(x.ttl)}</b><span>${fl(x.d)} · Phiên ${x.sess} · ${x.bias} · ${x.notes.length} nội dung · ${x.imgs.length} ảnh</span></div><span class="ar${o?' o':''}">▸</span></div>${o?`<div class="ab"><div class="kv"><div><span>Key level</span>${esc(x.lv)}</div><div><span>Kịch bản (Entry / SL / TP)</span>${esc(x.plan)}</div><div><span>Điều kiện huỷ</span>${esc(x.inv)}</div></div>${x.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<div class="imgs">${x.imgs.map(i=>`<img src="${i}" alt="">`).join('')}</div><h4>Feedback cuối ngày</h4><textarea rows="3" data-af="${x.id}:fb" placeholder="Làm đúng gì, sai gì, bài học, cảm xúc…">${esc(x.fb)}</textarea><div class="pf"><select data-af="${x.id}:sc"><option value="">Đánh giá 1–5</option>${[1,2,3,4,5].map(n=>`<option ${x.sc==n?'selected':''}>${n}</option>`).join('')}</select><label><input type="checkbox" data-af="${x.id}:ok" ${x.ok?'checked':''}> Đã tuân thủ quy định</label><button class="x" data-lg="del:ana:${x.id}">Xoá</button></div></div>`:''}</div>`};
return`${LG.msg?`<div class="card" style="margin-bottom:18px;border-color:var(--ok)"><b>${esc(LG.msg)}</b></div>`:''}${anaOverview(L)}<div class="card" style="margin-top:18px"><h3>Phân tích trade<span class="hr"><button class="bt" data-lg="add">+ Thêm phân tích</button></span></h3>${LG.adding?`<div class="fm"><input type="date" id="ad" value="${iso(dates[q[1]])}"><input id="at" placeholder="Tiêu đề, ví dụ: Phân tích vàng phiên Mỹ"><select id="as">${['Á','Âu','Mỹ'].map(op).join('')}</select><select id="ab">${['Tăng','Giảm','Đi ngang'].map(op).join('')}</select><input id="al" placeholder="Key level, ví dụ: 2350 / 2372"><input id="ap" placeholder="Kịch bản: Entry / SL / TP"><input id="ai" placeholder="Điều kiện huỷ kịch bản"><div id="ncs"><textarea class="anc" rows="2" placeholder="Nội dung (nhận định, lý do vào lệnh, tin tức…)"></textarea></div><button class="ii" data-lg="nc">+ Thêm nội dung</button><div id="adrop" class="drop">Kéo thả ảnh vào đây hoặc <label>chọn ảnh<input type="file" id="aimg" accept="image/*" multiple hidden></label></div><div class="fm" style="grid-template-columns:1fr auto"><input id="aurl" placeholder="Hoặc dán URL ảnh"><button class="ii" data-lg="aurl">Thêm từ URL</button></div><div id="aprev" class="imgs">${prevH()}</div><button class="bt" data-lg="addana">Lưu phân tích</button></div>`:''}${L.map(rw).join('')||'<p class="nt">Chưa có phân tích trong khoảng này.</p>'}${one?'':'<p class="nt">Chọn một ngày ở bộ lọc để xem đầy đủ phân tích của ngày đó.</p>'}</div>`}
function lgRule(T){const au=LGD.rul.filter(r=>r.auto),chk={sltp:x=>Math.abs(x.slD-20)<=1&&Math.abs(x.tpD-20)<=1,ana:x=>LGD.ana.some(z=>z.d==dOf(x.ts))},why={sltp:x=>`SL ${x.slD} / TP ${x.tpD} giá`,ana:x=>'chưa có phân tích ngày '+fl(dOf(x.ts))},rs=au.map(r=>{const bad=T.filter(x=>!chk[r.auto](x));return{r,bad,p:T.length?(T.length-bad.length)/T.length*100:0}}),tp=rs.length&&T.length?sm2(rs,x=>x.p)/rs.length:0,A=LGD.ana.filter(x=>inR(x.d));
const bar=p=>`<div class="bar"><u style="width:${p}%;background:${pcol(p)}"></u></div>`;
return`<div class="card" style="margin-top:18px"><h3>Kiểm tra quy định trade</h3><div class="row"><div><b>Tuân thủ chung (tự kiểm tra)</b><span>${T.length} lệnh trong phạm vi đang xem</span></div>${bar(tp)}<em style="color:${pcol(tp)}">${nf(tp,0)}%</em></div>${rs.map(x=>`<div class="row"><div><b>${esc(x.r.t)}</b><span>${x.bad.length} lệnh vi phạm</span></div>${bar(x.p)}<em style="color:${pcol(x.p)}">${nf(x.p,0)}%</em></div>${x.bad.slice(0,5).map(b=>`<div class="er"><small class="bad">${fts(b.ts)} · ${b.side} · ${why[x.r.auto](b)}</small></div>`).join('')}`).join('')}<p class="nt">Quy định cần tự đánh giá: ${LGD.rul.filter(r=>!r.auto).map(r=>esc(r.t)).join('; ')||'không có'}. Đã tick tuân thủ: ${A.filter(x=>x.ok).length}/${A.length} phân tích.</p></div>`}
function lgRes(){const q=rng(),a=iso(dates[q[0]]),b=iso(dates[q[1]]),all=LGD.trd.filter(x=>{const d=dOf(x.ts);return d>=a&&d<=b}),stt=ar=>{const w=ar.filter(x=>x.pnl>0),l=ar.filter(x=>x.pnl<0),W=sm2(w,x=>x.pnl),Z=-sm2(l,x=>x.pnl);return{n:ar.length,W,Z,net:W-Z,wr:ar.length?w.length/ar.length*100:0}},
cd=(id,nm,ar,k)=>{const s=stt(ar);return`<button class="ac2 ${LG.acc==id?'on':''}" data-lg="acct:${id}"><div class="an2"><b>${esc(nm)}</b>${k?`<span class="bd ${k}">${K2[k]}</span>`:''}</div><div class="st"><div><span>Số lệnh</span>${s.n}</div><div><span>Lãi</span><b class="ok">${usd(s.W)}</b></div><div><span>Lỗ</span><b class="bad">${usd(-s.Z)}</b></div><div><span>Tổng kết</span><b class="${s.net>=0?'ok':'bad'}">${usd(s.net)}</b></div><div><span>Winrate</span>${nf(s.wr,0)}%</div></div></button>`},
grp=k=>`<h3 style="margin:18px 0 0">Tài khoản ${K2[k].toLowerCase()}</h3><div class="cg2">${LGD.acc.filter(x=>x.k==k).map(x=>cd(x.id,x.n,all.filter(t=>t.acc==x.id),k)).join('')||'<p class="nt">Chưa có tài khoản.</p>'}</div>`,T=trList(),nmA=LG.acc=='all'?'Tất cả tài khoản':(LGD.acc.find(x=>x.id==LG.acc)||{}).n;
const tb=T.slice().reverse().map(x=>`<div class="trw" style="--c:${x.pnl>=0?'var(--ok)':'var(--bad)'}"><div><span>Thời gian</span>${fts(x.ts)}</div><div><span>Phiên</span>${x.sess}</div><div><span>Lệnh</span>${x.side} ${x.sym}</div><div><span>Vào</span>${x.entry}</div><div><span>SL</span>${x.sl} (${x.slD})</div><div><span>TP</span>${x.tp} (${x.tpD})</div><div><span>Khối lượng</span>${x.vol}</div><div><span>Kết quả</span><b class="${x.pnl>=0?'ok':'bad'}">${x.pnl>=0?'+':''}${usd(x.pnl)}</b></div></div>`).join('');
return`<div style="max-width:520px;margin-top:14px">${cd('all','Tất cả tài khoản',all,'')}</div>`+grp('t')+grp('q')+`<div class="card"><h3>${esc(nmA)} · ${T.length} lệnh<span class="hr"><span class="seg"><button class="${LG.view=='chart'?'on':''}" data-lg="vw:chart">Biểu đồ</button><button class="${LG.view=='table'?'on':''}" data-lg="vw:table">Dạng bảng</button></span></span></h3>${LG.view=='chart'?'<div class="cv" style="height:340px"><canvas id="tc"></canvas></div>':tb||'<p class="nt">Không có lệnh trong khoảng này.</p>'}</div>`+lgRule(T)}
function lgAcc(){const op=o=>`<option>${o}</option>`,n=k=>LGD.acc.filter(x=>x.k==k).length,rw=x=>`<div class="er"><div><b>${esc(x.n)}</b><span>${esc(x.srv)} · Đòn bẩy ${esc(x.lev)} · ${esc(x.cur)} · ${esc(x.st)}${x.pw?' · Mật khẩu ••••••':''}${x.k=='q'?' · Khối lượng '+x.vol+' lot':''}</span></div><div style="text-align:right"><span class="bd ${x.k}">${K2[x.k]}</span><br><button class="x" data-lg="del:acc:${x.id}">Xoá</button></div></div>`;
return`<div class="card"><h3>Tài khoản · tổng ${LGD.acc.length}<span class="hr"><button class="bt" data-lg="add">+ Thêm tài khoản</button></span></h3><p class="nt" style="margin:0 0 8px"><span class="bd t">Thường ${n('t')}</span> <span class="bd q">Quỹ ${n('q')}</span></p>${LG.adding?`<div class="fm"><input id="an" placeholder="Tên tài khoản"><select id="ck"><option value="t">Tài khoản thường</option><option value="q">Tài khoản quỹ</option></select><input id="cs" placeholder="Máy chủ (server)"><input id="cl" placeholder="Đòn bẩy, ví dụ 1:500"><input id="cc" placeholder="Tiền tệ" value="USD"><input id="cp" type="password" placeholder="Mật khẩu" autocomplete="off"><select id="cst">${['Hoạt động','Tạm dừng','Đã đóng'].map(op).join('')}</select><input id="cv" data-money="pos" inputmode="numeric" placeholder="Khối lượng (chỉ tài khoản quỹ)"><button class="bt" data-lg="addacc">Thêm tài khoản</button></div>`:''}<h3 style="margin:14px 0 0">Tài khoản thường</h3>${LGD.acc.filter(x=>x.k=='t').map(rw).join('')||'<p class="nt">Chưa có.</p>'}<h3 style="margin:14px 0 0">Tài khoản quỹ</h3>${LGD.acc.filter(x=>x.k=='q').map(rw).join('')||'<p class="nt">Chưa có.</p>'}</div>`}
const lgRul=()=>`<div class="card"><h3>Quy định trade</h3><div class="fm" style="grid-template-columns:1fr auto"><input id="rn" placeholder="Quy tắc mới, ví dụ: Không giữ lệnh qua tin lớn"><button class="bt" data-lg="addrul">Thêm quy tắc</button></div>${LGD.rul.map(r=>`<div class="row r2"><div><b>${esc(r.t)}</b><span>${r.auto?'Tự kiểm tra trong Kết quả trade':'Tự đánh giá trong Phân tích'}</span></div><button class="x" data-lg="del:rul:${r.id}">Xoá</button></div>`).join('')}</div>`;
const lgSch=()=>`<div class="card"><h3>Lịch trade</h3><div class="fm"><input class="t24" inputmode="numeric" placeholder="HH:MM" maxlength="5" id="ss"><input class="t24" inputmode="numeric" placeholder="HH:MM" maxlength="5" id="se"><input id="st" placeholder="Tên, ví dụ: Vẽ trend"><div class="pf">${WD.map((w,i)=>`<label><input type="checkbox" class="dchk" value="${i}" ${i<5?'checked':''}> ${w}</label>`).join('')}</div><button class="bt" data-lg="addsch">Thêm lịch</button></div>${LGD.sch.map(x=>`<div class="row r2"><div><b>${x.s==0&&x.e==1440?'Cả ngày':tm(x.s)+'–'+tm(x.e)} · ${esc(x.t)}</b><span>${x.days.map(i=>WD[i]).join(', ')}</span></div><button class="x" data-lg="del:sch:${x.id}">Xoá</button></div>`).join('')}</div>`;
const DT=['Vốn','Lợi nhuận','Doanh thu','Phân tích','Kết quả trade','Tài khoản','Quy định','Lịch trade'],lgDoc=()=>`<div class="card"><h3>Tài liệu (file Sheet)</h3><div class="fm"><select id="dt">${DT.map(o=>`<option>${o}</option>`).join('')}</select><input id="du" placeholder="Dán link Google Sheet"><button class="bt" data-lg="adddoc">Thêm tài liệu</button></div>${LGD.doc.map(x=>`<div class="row r2"><div><b>${esc(x.t)}</b><span>${esc(x.u)}</span></div><button class="x" data-lg="del:doc:${x.id}">Xoá</button></div>`).join('')||'<p class="nt">Chưa có file nào. Khi nối Sheet, dữ liệu mỗi mục sẽ lấy từ file tương ứng và thao tác trên giao diện sẽ ghi ngược lại file.</p>'}</div>`;
function legdHtml(){const T=[['ov','Tổng quan'],['ana','Phân tích'],['res','Kết quả trade'],['acc','Tài khoản'],['rul','Quy định'],['sch','Lịch trade'],['doc','Tài liệu']];return`<div class="seg wk">${T.map(x=>`<button data-lg="tab:${x[0]}" class="${LG.tab==x[0]?'on':''}">${x[1]}</button>`).join('')}</div><div style="margin-top:18px">${({ov:lgOv,ana:lgAna,res:lgRes,acc:lgAcc,rul:lgRul,sch:()=>areaCalH('legd','Lịch trade'),doc:()=>sheetsH('legd')})[LG.tab]()}</div>`}
function tradeChart(){const T=trList(),L=[],D=[];let c=0;T.forEach(x=>{c+=x.pnl;L.push(fts(x.ts));D.push(+c.toFixed(2))});
return new Chart(document.getElementById('tc'),{type:'line',data:{labels:L,datasets:[{label:'Lãi/lỗ lũy kế',data:D,borderColor:cv('gold'),backgroundColor:x=>grad(x,cv('gold')),fill:'origin',tension:.25,borderWidth:2.4,pointRadius:T.length>80?0:3,pointHoverRadius:6,pointBackgroundColor:T.map(x=>x.pnl>=0?cv('ok'):cv('bad'))}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'nearest',intersect:false},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>' Lũy kế: '+usd(c.parsed.y),afterBody:i=>{const x=T[i[0].dataIndex];return['Phiên '+x.sess+' · '+x.side+' '+x.sym,'Vào '+x.entry+' · SL '+x.sl+' ('+x.slD+') · TP '+x.tp+' ('+x.tpD+')','Khối lượng '+x.vol+' lot','Kết quả '+(x.pnl>=0?'+':'')+usd(x.pnl)]}}}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:8}},y:{grid:{color:cv('line')},border:{display:false},ticks:{callback:v=>usd(v)}}}}})}
async function addAna(){const d=$('#ad').value||tdy();let ttl=$('#at').value.trim();if(!ttl)ttl='Phân tích '+fl(d);const notes=[...document.querySelectorAll('.anc')].map(x=>x.value.trim()).filter(Boolean),imgs=[...ANAI];LGD.ana.push({id:uid(),d,ttl,sess:$('#as').value,bias:$('#ab').value,lv:$('#al').value,plan:$('#ap').value,inv:$('#ai').value,notes,imgs,fb:'',sc:'',ok:false});ANAI.length=0;lgsv('ana');LG.adding=false;const q=rng(),shown=d>=iso(dates[q[0]])&&d<=iso(dates[q[1]]);LG.msg='Đã lưu "'+ttl+'" ngày '+fl(d)+(shown?'':'. Ngày này nằm ngoài khoảng thời gian đang lọc nên chưa hiện, hãy chọn lại bộ lọc để xem.');render()}
$('#main').addEventListener('click',ev=>{const t=ev.target.closest('[data-lg]');if(!t||cur!='legd')return;const q=t.dataset.lg.split(':'),a=q[0],b=q[1],c=q[2],V=i=>$(i).value;
if(a=='tab'){LG.tab=b;LG.adding=false}
else if(a=='sec'){LG.sec=b;LG.adding=false}
else if(a=='add'){LG.adding=!LG.adding;ANAI.length=0}
else if(a=='nc'){const x=document.createElement('textarea');x.className='anc';x.rows=2;x.placeholder='Nội dung tiếp theo';$('#ncs').appendChild(x);return}
else if(a=='acct')LG.acc=b;
else if(a=='vw')LG.view=b;
else if(a=='ao')LG.open=LG.open==b?null:b;
else if(a=='del'){LGD[b]=LGD[b].filter(x=>x.id!=c);lgsv(b)}
else if(a=='addent'){const v=num(V('#la'));if(!v)return;const de=iso(dates[rng()[1]]),d=de>tdy()?tdy():de;LGD[LG.sec].push({id:uid(),d,a:v,ty:V('#lt'),n:V('#lc').trim(),ts:d==tdy()?Date.now():+new Date(d+'T12:00')});lgsv(LG.sec);LG.adding=false}
else if(a=='aurl'){const u=V('#aurl').trim();if(!u)return;ANAI.push(u);prevUpdate();$('#aurl').value='';return}
else if(a=='rmimg'){ANAI.splice(+b,1);prevUpdate();return}
else if(a=='cmp')LG.cmp=b;
else if(a=='addana'){addAna();return}
else if(a=='addacc'){const n=V('#an').trim();if(!n)return;LGD.acc.push({id:uid(),n,k:V('#ck'),srv:V('#cs'),lev:V('#cl'),cur:V('#cc'),pw:V('#cp'),st:V('#cst'),vol:num(V('#cv'))||0});lgsv('acc');LG.adding=false}
else if(a=='addrul'){const x=V('#rn').trim();if(!x)return;LGD.rul.push({id:uid(),t:x});lgsv('rul')}
else if(a=='addsch'){const P=i=>{const z=V(i).split(':');return+z[0]*60+ +z[1]},s=P('#ss');let e=P('#se');const n=V('#st').trim();if(isNaN(s)||isNaN(e)||!n)return;if(e<=s)e+=1440;LGD.sch.push({id:uid(),s,e,t:n,days:[...document.querySelectorAll('.dchk')].filter(x=>x.checked).map(x=>+x.value)});lgsv('sch')}
else if(a=='adddoc'){const u=V('#du').trim();if(!u)return;LGD.doc.push({id:uid(),t:V('#dt'),u});lgsv('doc')}
render()});
