async function logout(){if(API){if(SAVE.dirty)await doSave();await api('POST','/api/auth',{action:'logout'})}clearApp();SAVE.dirty=false;location.reload()}
let STM='',stmT=null;const setMsg=m=>{STM=m;const e=document.getElementById('stm');if(e)e.textContent=m;clearTimeout(stmT);stmT=setTimeout(()=>{STM='';const x=document.getElementById('stm');if(x)x.textContent=''},6000)};
async function loadUsers(){const r=await api('GET','/api/users');if(r.s==200){USERS=r.j.users;render()}}
async function stUpd(body,ok){const r=await api('POST','/api/users',{action:'update',...body});if(r.s==200){if(ok)ok();if(r.j.user&&r.j.user.username==ME.username)ME=r.j.user;shell();await loadUsers()}else setMsg((r.j&&r.j.error)||'Lỗi ('+r.s+')')}
function setHtml(){
if(!API)return'<div class="card" style="margin-top:22px"><h3>Chế độ cục bộ</h3><p class="nt">Ứng dụng đang chạy không có máy chủ nên không có đăng nhập và dữ liệu chỉ lưu trong trình duyệt này. Đăng nhập theo từng tài khoản và lưu dữ liệu trên máy chủ chỉ hoạt động trên bản đã triển khai trên Vercel.</p></div>';
if(!ULOAD){ULOAD=true;loadUsers()}
const adm=ME.role=='admin';
let h=`<div class="card" style="margin-top:22px"><h3>Tài khoản của bạn</h3><div class="pf" style="align-items:center"><span class="avb">${avH(ME)}</span><div><b>${esc(ME.name)}</b><br><span class="nt">${esc(ME.username)} · ${ME.role=='admin'?'Quản trị viên':'Người dùng'}</span></div><button class="ii" data-st="logout">Đăng xuất</button></div><h3 style="margin-top:16px">Ảnh đại diện (thay logo trên thanh bên)</h3><div class="pf">${AVS.map(a=>`<button class="avc" data-st="av|${a}">${a}</button>`).join('')}<button class="avc" data-st="av|" title="Chữ cái đầu của tên">Aa</button></div><div class="fm"><input type="file" id="avf" accept="image/*"></div><h3 style="margin-top:16px">Đổi mật khẩu</h3><div class="fm"><input id="cp" type="password" placeholder="Mật khẩu hiện tại" autocomplete="current-password"><input id="np" type="password" placeholder="Mật khẩu mới (từ 6 ký tự)" autocomplete="new-password"><button class="bt" data-st="pw">Đổi mật khẩu</button></div><p class="nt" id="stm">${esc(STM)}</p></div>`;
if(adm)h+=`<div class="card" style="margin-top:18px"><h3>Quản lý người dùng</h3><p class="nt" style="margin:0 0 8px">Mỗi tài khoản có dữ liệu riêng, không ai xem được dữ liệu của tài khoản khác.</p>${USERS.map(u=>`<div class="er"><div class="pf" style="align-items:flex-start;flex:1;margin:0"><span class="avb">${avH(u)}</span><div style="flex:1"><b>${esc(u.name)}</b> <span class="bd ${u.role=='admin'?'q':'t'}">${u.role=='admin'?'Quản trị':'Người dùng'}</span><span>${esc(u.username)}</span><select data-rl="${esc(u.username)}" aria-label="Vai trò"><option value="user" ${u.role!='admin'?'selected':''}>Người dùng</option><option value="admin" ${u.role=='admin'?'selected':''}>Quản trị viên</option></select>${u.role=='admin'?'<span class="nt">Xem tất cả các mục</span>':`<div class="pf" style="margin-top:6px">${PERM_PAGES.map(k=>`<label><input type="checkbox" data-pm="${esc(u.username)}|${k}" ${(u.perms||[]).includes(k)?'checked':''}> ${PG[k].n}</label>`).join('')}</div>`}</div></div>${u.username==ME.username?'':`<button class="x" data-st="del|${esc(u.username)}">Xoá</button>`}</div>`).join('')||'<p class="nt">Đang tải…</p>'}<h3 style="margin-top:16px">Thêm người dùng</h3><div class="fm"><input id="un" placeholder="Tên hiển thị"><div class="pf" style="align-items:center"><span class="avb" id="nuprev">${avH({av:NUAV,name:'?'})}</span>${AVS.map(a=>`<button class="avc" data-st="nav|${a}">${a}</button>`).join('')}<button class="avc" data-st="nav|" title="Chữ cái đầu của tên">Aa</button></div><input type="file" id="nuf" accept="image/*" aria-label="Tải ảnh đại diện"><input id="uu" placeholder="Tên đăng nhập (a-z, 0-9, . _ -)" autocomplete="off"><input id="up" type="password" placeholder="Mật khẩu (từ 6 ký tự)" autocomplete="new-password"><select id="ur"><option value="user">Người dùng (chỉ xem các mục được tick)</option><option value="admin">Quản trị viên (xem tất cả)</option></select><div class="pf">${PERM_PAGES.map(k=>`<label><input type="checkbox" class="upm" value="${k}" checked> ${PG[k].n}</label>`).join('')}</div><button class="bt" data-st="add">Tạo tài khoản</button></div></div>`;
return h}
async function addUser(){const n=$('#un').value.trim(),u=$('#uu').value.trim().toLowerCase(),p=$('#up').value;if(!n||!u||p.length<6){setMsg('Nhập đủ tên, tên đăng nhập và mật khẩu (từ 6 ký tự)');return}const r=await api('POST','/api/users',{action:'create',name:n,username:u,password:p,role:$('#ur').value,perms:[...document.querySelectorAll('.upm')].filter(x=>x.checked).map(x=>x.value),av:NUAV});if(r.s==200){NUAV='';await loadUsers()}else setMsg((r.j&&r.j.error)||'Lỗi ('+r.s+')')}
$('#main').addEventListener('click',ev=>{const t=ev.target.closest('[data-st]');if(!t||cur!='set')return;const q=t.dataset.st.split('|'),a=q[0];
if(a=='logout'){logout();return}
if(a=='nav'){NUAV=q[1];updPrev();return}
if(a=='av'){stUpd({username:ME.username,av:q[1]});return}
if(a=='pw'){const np=$('#np').value;if(np.length<6){setMsg('Mật khẩu mới cần từ 6 ký tự');return}stUpd({username:ME.username,password:np,currentPassword:$('#cp').value},()=>{setMsg('Đã đổi mật khẩu')});return}
if(a=='add'){addUser();return}
if(a=='del'){api('POST','/api/users',{action:'delete',username:q[1]}).then(r=>{if(r.s==200)loadUsers();else setMsg((r.j&&r.j.error)||'Lỗi ('+r.s+')')})}});
$('#main').addEventListener('change',ev=>{const t=ev.target;if(cur!='set')return;
if(t.dataset.pm){const q=t.dataset.pm.split('|'),u=USERS.find(x=>x.username==q[0]);if(!u)return;const ps=new Set(u.perms||[]);if(t.checked)ps.add(q[1]);else ps.delete(q[1]);stUpd({username:u.username,perms:[...ps]})}
else if(t.dataset.rl){stUpd({username:t.dataset.rl,role:t.value})}
else if(t.id=='nuf'&&t.files&&t.files[0]){rdS(t.files[0],128,.85).then(d=>{if(d){NUAV=d;updPrev()}})}
else if(t.id=='avf'&&t.files&&t.files[0]){rdS(t.files[0],128,.85).then(d=>{if(d)stUpd({username:ME.username,av:d})})}});
let NUAV='';
function drawer(o){const s=document.querySelector('.side'),c=document.getElementById('scrim'),b=document.getElementById('bg');if(s)s.classList.toggle('open',o);if(c)c.classList.toggle('on',o);if(b&&b.setAttribute)b.setAttribute('aria-expanded',String(o))}
function mbarUpd(){const t=document.getElementById('mt');if(t)t.textContent=(PG[cur]||{}).n||'Life System';const a=document.getElementById('mav');if(a)a.innerHTML=avH(ME)}
const updPrev=()=>{const e=document.getElementById('nuprev');if(e)e.innerHTML=avH({av:NUAV,name:(document.getElementById('un')||{}).value||'?'})};
{const bg=document.getElementById('bg'),sc=document.getElementById('scrim');if(bg)bg.onclick=()=>drawer(true);if(sc)sc.onclick=()=>drawer(false);document.addEventListener('keydown',e=>{if(e.key=='Escape')drawer(false)})}
function render(){
if(!canSee(cur))cur=firstOk();CH.forEach(c=>c.destroy());CH=[];
const p=PG[cur],[s,e]=rng(),D=Chart.defaults,hr=new Date().getHours();
D.font.family='Manrope,sans-serif';D.color=cv('mut');D.animation=RM?false:{duration:900,easing:'easeOutQuart'};
Object.assign(D.plugins.tooltip,{backgroundColor:cv('card'),titleColor:cv('ink'),bodyColor:cv('mut'),borderColor:cv('line'),borderWidth:1,padding:12,boxPadding:5,cornerRadius:10});
D.plugins.legend.labels.usePointStyle=true;
const title=cur=='stats'?(hr<11?'Chào buổi sáng':hr<18?'Chào buổi chiều':'Chào buổi tối'):p.n;
let h=`<header><h1>${title}</h1><p>${p.d}</p></header>`;
if(cur=='set'){h+=setHtml()}else if(cur=='today'){h+=todayHtml()}else if(cur=='goal'){h+=goalHtml()}else if(cur=='cal'){h+=calHtml()}else if(cur=='sys'){h+=sysHtml()}else if(cur=='acc'){h+=bankHtml()}else if(cur=='accold'){const tot=ACC.reduce((a,x)=>a+x[2],0);
h+=`<div class="g" style="margin-top:26px"><div class="card s2"><h3>Số dư các tài khoản</h3><div class="tot"><b data-v="${tot}" data-d="1">0</b><i>tr đ</i></div>${ACC.map(a=>`<div class="row"><div><b>${a[0]}</b><span>${a[1]}</span></div><div class="bar"><u style="width:${a[2]/tot*100}%"></u></div><em>${nf(a[2],1)} tr</em></div>`).join('')}</div>
<div class="card"><h3>Kết nối Google Sheet</h3>${['LEGD','Business','English','PageFly','Cá nhân','Tài chính'].map(n=>`<div class="row r2"><div><b>${n}</b><span>Tab “${n}”</span></div><span class="pill">Dữ liệu mẫu</span></div>`).join('')}<p class="nt">Mỗi mảng đọc từ một tab riêng. Hiện đang hiển thị dữ liệu mẫu.</p></div></div>`}
else{
const seg=[['7','7 ngày'],['30','30 ngày'],['90','90 ngày'],['d','Ngày'],['wk','Tuần'],['mo','Tháng'],['rg','Tuỳ chọn']],len=e-s+1;
const ex=F.m=='d'?`<input type="date" data-f="d" value="${F.d}" min="${iso(dates[0])}" max="${iso(dates[N-1])}">`:F.m=='wk'?`<select data-f="wk" aria-label="Từ tuần">${WK.map((w,i)=>`<option value="${i}" ${i==F.wk?'selected':''}>Từ ${w.l}</option>`).join('')}</select><select data-f="wk2" aria-label="Đến tuần">${WK.map((w,i)=>`<option value="${i}" ${i==(F.wk2==null?F.wk:F.wk2)?'selected':''}>Đến ${w.l}</option>`).join('')}</select>`:F.m=='mo'?`<select data-f="mo" aria-label="Từ tháng">${MO.map((w,i)=>`<option value="${i}" ${i==F.mo?'selected':''}>Từ ${w.l}</option>`).join('')}</select><select data-f="mo2" aria-label="Đến tháng">${MO.map((w,i)=>`<option value="${i}" ${i==(F.mo2==null?F.mo:F.mo2)?'selected':''}>Đến ${w.l}</option>`).join('')}</select>`:F.m=='rg'?`<input type="date" data-f="a" value="${F.a}" min="${iso(dates[0])}" max="${iso(dates[N-1])}"><input type="date" data-f="b" value="${F.b}" min="${iso(dates[0])}" max="${iso(dates[N-1])}">`:'';
h+=`<div class="fb"><div class="seg">${seg.map(([m,l])=>`<button data-m="${m}" class="${F.m==m?'on':''}">${l}</button>`).join('')}</div>${ex}<span class="rt">${fd(dates[s])} – ${fd(dates[e])}/${dates[e].getFullYear()} · ${len} ngày${len>45?' · gộp theo tuần':''}</span></div>`;
h+=CUSTOM[cur]?CUSTOM[cur]():`<div class="k">${p.k.map(k=>kpi(k,s,e)).join('')}${p.x?p.x(s,e):''}</div><div class="g">${p.c.map((c,i)=>`<div class="card ${c.s==2?'s2':c.s==3?'s3':''}"><h3>${c.h}</h3>${c.t=='heat'?`<div class="hm">${heat(s,e)}</div>`:`<div class="cv"><canvas id="c${i}"></canvas></div>`}</div>`).join('')}</div>`}
if(AREA[cur])h+=docH(cur);const sw0=document.querySelector('.shw'),pk0=cur+AT[cur]+LG.tab+JSON.stringify(SH.sel);if(sw0&&SK==pk0){SL=sw0.scrollLeft;SVT=sw0.scrollTop}else{SL=0;SVT=0}$('#main').innerHTML=h;const nw0=document.querySelector('.shw');if(nw0&&SK==pk0){nw0.scrollLeft=SL;nw0.scrollTop=SVT}SK=pk0;mbarUpd();cu();if(cur=='goal')goalAfter();if(cur=='fin')finAfter();if(cur=='legd'&&LG.tab=='res'&&LG.view=='chart'&&document.getElementById('tc'))CH.push(tradeChart());if(cur=='legd'&&LG.tab=='ana'&&LG.cmp=='chart'&&document.getElementById('ac'))CH.push(anaChart());
if(!['acc','cal','sys','today','goal','fin','legd','biz','eng','pf','per','set'].includes(cur))p.c.forEach((c,i)=>{if(c.t!='heat')CH.push(chart('c'+i,c,s,e))})}
function buildNav(){$('#nav').innerHTML=NAVORD.filter(k=>PG[k]&&canSee(k)).map(k=>`<button class="nv ${k==cur?'on':''}" data-p="${k}" title="${PG[k].n}"><svg viewBox="0 0 24 24">${I[k]}</svg><span>${PG[k].n}</span></button>`).join('')}buildNav();
$('#nav').onclick=ev=>{const b=ev.target.closest('[data-p]');if(!b)return;cur=b.dataset.p;drawer(false);document.querySelectorAll('.nv').forEach(n=>n.classList.toggle('on',n==b));scrollTo(0,0);render()};
$('#main').onclick=ev=>{const b=ev.target.closest('[data-m]');if(b){F.m=b.dataset.m;render()}};
$('#main').onchange=ev=>{const f=ev.target.dataset.f;if(!f||!ev.target.value)return;F[f]=f=='a'||f=='b'||f=='d'?ev.target.value:+ev.target.value;render()};
SYNR=true;shell();if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>render());else render();
